// docs/PG_INVENTORY.md is a snapshot generated from the source (lib/db/pg-inventory.ts), regenerated by each port slice:
//   node --experimental-strip-types scripts/pg-migrate/inventory.mts --write
// It is not held byte-for-byte (any new test file would change it); the gate itself is lib/db/pg-port-status.ts, held by
// test/pg-sql-audit.test.ts. What this file holds: the detectors, and that every module-level Map/Set is classified.
import test from 'node:test'
import assert from 'node:assert/strict'
import { join } from 'node:path'
import { buildInventory, renderInventory, DIALECT, areaOf, STATE_NOTES } from '../lib/db/pg-inventory.ts'
import { RAW_SQLITE_MODULES } from '../lib/db/pg-port-status.ts'

const root = join(import.meta.dirname, '..')

test('the inventory renders every raw module and agrees with the manifest totals', () => {
  const inv = buildInventory(root)
  const md = renderInventory(inv)
  for (const m of inv.modules) assert.ok(md.includes(`\`${m.file}\``), m.file)
  assert.equal(inv.totals.raw, Object.keys(RAW_SQLITE_MODULES).length)
  assert.equal(inv.totals.rejected, Object.values(RAW_SQLITE_MODULES).reduce((a, b) => a + b, 0))
})

test('dialect detectors flag the SQLite-only constructs and leave portable SQL alone', () => {
  const hit = (sql: string) => DIALECT.filter(d => d.re.test(sql)).map(d => d.id)
  assert.deepEqual(hit("INSERT OR IGNORE INTO t (a) VALUES (?)"), ['insert-or'])
  assert.deepEqual(hit("UPDATE t SET at = CAST(strftime('%s','now') AS INTEGER)"), ['strftime-now'])
  assert.deepEqual(hit('SELECT id FROM t ORDER BY created_at DESC, rowid DESC'), ['rowid'])
  assert.deepEqual(hit('UPDATE t SET v = MAX(COALESCE(v, 0) - 1, 0)'), ['scalar-max-min'])
  assert.deepEqual(hit("SELECT 1 FROM sqlite_master WHERE name = ?"), ['sqlite_master'])
  assert.deepEqual(hit('SELECT MAX(a) FROM t WHERE b = ? ON CONFLICT DO NOTHING'), [])
  assert.deepEqual(hit('INSERT INTO t (a) VALUES (?) ON CONFLICT (a) DO UPDATE SET b = excluded.b'), [])
})

test('every raw module is placed in a product area', () => {
  assert.equal(areaOf('lib/outreach/send-budget.ts'), 'sends')
  assert.equal(areaOf('lib/outreach/replies.ts'), 'inbox')
  assert.equal(areaOf('lib/auth-db.ts'), 'auth & keys')
  assert.deepEqual(buildInventory(root).modules.filter(m => m.area === 'other').map(m => m.file), [])
})

test('every module-level Map/Set is classified (shared state vs. a cache safe to lose)', () => {
  const inv = buildInventory(root)
  const keys = inv.state.map(s => `${s.file}:${s.name}`)
  assert.deepEqual(keys.filter(k => !STATE_NOTES[k]), [], 'classify it in STATE_NOTES (lib/db/pg-inventory.ts)')
  assert.deepEqual(Object.keys(STATE_NOTES).filter(k => !keys.includes(k)), [], 'gone from the source: remove it from STATE_NOTES')
})
